#!/usr/bin/env node
// Russian mirrors from the English pages (roadmap item 75). An English page
// that starts with the marker line opts in: its app/ru twin is generated by
// swapping the locale ("en" → "ru") — metadata comes from the route registry
// (lib/routes/metadata.ts), text from the components' *Copy.ts, so nothing
// else differs. Hand-written mirrors stay where a page needs them; routes:check
// keeps both kinds paired.
//   npm run routes:mirror              write the generated mirrors
//   npm run routes:mirror -- --check   fail when a mirror is stale (CI, via routes:check)
//   npm run routes:mirror -- --candidates   hand-written pairs that could opt in as they are
import fs from "node:fs";
import path from "node:path";

const root = path.resolve(path.dirname(new URL(import.meta.url).pathname), "..");
const site = path.join(root, "app", "(site)");
const ru = path.join(root, "app", "ru");
export const MARKER = "// routes:mirror — app/ru twin is generated from this page (npm run routes:mirror).";
const files = ["page.tsx", "opengraph-image.tsx"];

function* walk(dir, rel = "") {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (entry.isDirectory()) yield* walk(path.join(dir, entry.name), rel ? `${rel}/${entry.name}` : entry.name);
    else if (files.includes(entry.name)) yield rel ? `${rel}/${entry.name}` : entry.name;
  }
}

const header = (rel) => `// Generated from app/(site)/${rel} by npm run routes:mirror — edit the English page.`;
/** The Russian twin of an English page: the locale literal is the only difference. */
export function mirror(source, rel) {
  return source.replace(MARKER, header(rel)).replaceAll('"en"', '"ru"');
}

const mode = process.argv.includes("--check") ? "check" : process.argv.includes("--candidates") ? "candidates" : "write";
const stale = [];
const candidates = [];
let generated = 0;
for (const rel of walk(site)) {
  const english = fs.readFileSync(path.join(site, rel), "utf8");
  const target = path.join(ru, rel);
  const current = fs.existsSync(target) ? fs.readFileSync(target, "utf8") : null;
  if (!english.startsWith(MARKER)) {
    if (mode === "candidates" && current !== null && mirror(`${MARKER}\n${english}`, rel) === `${header(rel)}\n${current}`) candidates.push(rel);
    continue;
  }
  generated += 1;
  const expected = mirror(english, rel);
  if (current === expected) continue;
  if (mode === "check") stale.push(`app/ru/${rel}`);
  else if (mode === "write") {
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, expected);
    console.log(`wrote app/ru/${rel}`);
  }
}

if (mode === "candidates") {
  console.log(candidates.length ? candidates.map((rel) => `app/(site)/${rel}`).join("\n") : "no hand-written pair is a plain locale swap");
} else if (stale.length) {
  console.error(`${stale.join("\n")}\n\nroutes:mirror — ${stale.length} generated mirror(s) out of date: run npm run routes:mirror.`);
  process.exit(1);
} else console.log(`routes:mirror — ${generated} generated mirror(s) up to date.`);
